args.command:
node -e "
const Joi = require('joi');
const schema = Joi.object({ a: Joi.string() });
console.log('validate unknown default:', schema.validate({a:'hi', b:'extra'}));
console.log('validate with unknown true:', schema.unknown(true).validate({a:'hi', b:'extra'}));
console.log('joi version', require('joi/package.json').version);
// test expectBody pattern
const s2 = Joi.object({ resources: Joi.array().items(Joi.string().required()).required(), expectBody: Joi.alternatives().try(Joi.string(), Joi.object().instance(RegExp)) });
console.log('alt string', s2.validate({resources:['a'], expectBody: 'hello'}));
console.log('alt regex', s2.validate({resources:['a'], expectBody: /hello/}));
console.log('alt regex error', s2.validate({resources:['a'], expectBody: 123}));
"

